import importlib, driver, numpy as np, math
importlib.reload(driver)
# measure body height for a family of symmetric stance postures scaled around home
r=driver.build()
for _ in range(2000): r.apply_pd_posture(r._stand); r.step(1)
lo,hi=r._joint_lo,r._joint_hi
def stance(th,ca):
    return np.clip(np.array([0,th,ca, 0,th,ca, 0,-th,-ca, 0,-th,-ca],float),lo,hi)
for scale in (0.6,0.8,1.0,1.2,1.4):
    th=0.6*scale; ca=-1.1*scale
    q=stance(th,ca)
    for _ in range(1200): r.apply_pd_posture(q); r.step(1)
    print(f"scale={scale} th={th:.2f} ca={ca:.2f} -> h={r.get_body_height():.3f} rp={tuple(round(v,2) for v in r._roll_pitch())}")
